const LEGACY_CAPACITY_KWH = 50;                              // Kapazität für Einträge ohne gespeicherten Wert (ältere Ladungen)
const capOf = (r) => r.capacityKwh ?? LEGACY_CAPACITY_KWH;   // Kapazität, die zum Zeitpunkt dieser Ladung galt
