  if (withVin && !/^[A-HJ-NPR-Z0-9]{17}$/.test(vin)) throw new Error(vin ? 'Die VIN hat 17 Zeichen (Buchstaben und Ziffern, ohne I, O, Q).' : 'Bitte die VIN eingeben.');
