        txt(pg, err || 'Unbekannter Fehler', 60, 592, { size: 10, color: grey, w: 475 }); txt(pg, 'Original in Google Drive:', 60, 560, { size: 10, color: grey }); txt(pg, dvLink(f[i].id), 60, 544, { size: 9, color: COL.service, w: 475 });
