    const a = document.createElement('a'); a.href = url; a.download = 'Checkheft ' + ((getSettings().model || 'Enyaq').trim()) + ' ' + wxIso(new Date()) + '.pdf'; document.body.appendChild(a); a.click(); a.remove();
