  const lines = [['Start', 'Ende', 'Kategorie', 'Von', 'Nach', 'Startadresse', 'Zieladresse', 'km', 'km-Stand Start', 'km-Stand Ende', 'Fahrzeit min', 'kWh', 'kWh/100 km', 'Akku Start %', 'Akku Ende %'].map(q).join(';')]
