const btTripTxt = (e) => { const t = e.trip; if (!t) return ''; if (t.k === 'fahrt') return (t.ago != null ? t.ago + ' min nach ' : 'nach ') + (t.min ? t.min + ' min' : '') + (t.km ? ' / ' + t.km + ' km' : '') + ' Fahrt'; return t.h ? t.h + ' h geparkt' : ''; };
